test("公開名を binding 先と違う名前にした部品で、幅のモードを上書きで fixed にすると、公開した長さの欄が出る", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "renamed-card",
    overrides: { mode: "fixed" },
  });

  expect(publicPropNames(selection)).toEqual(["mode", "size"]);
});

test("部品の中でノードの幅のモードが fixed なら、モードを公開していなくても公開した長さの欄が出る", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "fixed-inside-card",
  });

  expect(publicPropNames(selection)).toEqual(["width"]);
});

test("部品の中で幅のモードが fixed でも、インスタンスがモードの公開 prop を hug に上書きすれば長さの欄は出ない", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "fixed-mode-card",
    overrides: { mode: "hug" },
  });

  expect(publicPropNames(selection)).toEqual(["mode"]);
});

test("置き方を上書きで絶対配置にしても、別のノードの座標へ繋いだ公開 prop の欄は出ない", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "split-card",
    overrides: { placement: "absolute" },
  });

  expect(publicPropNames(selection)).toEqual(["placement", "x"]);
});

test("部品の中でノードが絶対配置なら、置き方を公開していなくても、そのノードの座標へ繋いだ公開 prop の欄が出る", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "absolute-inside-card",
  });

  expect(publicPropNames(selection)).toEqual(["placement", "y"]);
});

test("入れ子の部品へ公開名を変えて繋いだ幅のモードを上書きで fixed にすると、長さの欄が出る", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "sizing-outer",
    overrides: { mode: "fixed" },
  });

  expect(publicPropNames(selection)).toEqual(["mode", "size"]);
});

test("部品定義の中の参照ノードが幅のモードを fixed に上書きしていれば、公開した長さの欄が出る", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "sizing-preset",
  });

  expect(publicPropNames(selection)).toEqual(["size"]);
});

test("条件の prop を公開していれば、公開 prop の欄の条件の行はその公開名になる", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "sized-card",
    overrides: { widthMode: "fixed" },
  });

  expect(
    controlNamed(instanceOf(selection).publicProps, "width").enabledBy,
  ).toEqual(Option.some("widthMode"));
});

test("条件の prop を公開していなければ、公開 prop の欄に条件の行は無い", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "fixed-inside-card",
  });

  expect(
    controlNamed(instanceOf(selection).publicProps, "width").enabledBy,
  ).toEqual(Option.none);
});

test("条件の prop を別の名前で公開していれば、公開 prop の欄の条件の行はその公開名になる", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "renamed-card",
    overrides: { mode: "fixed" },
  });

  expect(
    controlNamed(instanceOf(selection).publicProps, "size").enabledBy,
  ).toEqual(Option.some("mode"));
});

test("別のノードの置き方を公開していても、座標の公開 prop の欄に条件の行は無い", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "absolute-inside-card",
  });

  expect(
    controlNamed(instanceOf(selection).publicProps, "y").enabledBy,
  ).toEqual(Option.none);
});

test("上書きしている公開 prop でも、既定には部品が設定している値が出る", () => {
  const selection = setupInstanceSelection({
    name: "action",
    ref: "primary-button",
    overrides: { label: "ログイン" },
  });

  expect(
    controlNamed(instanceOf(selection).publicProps, "label").defaultValue,
  ).toEqual(Option.some("Button"));
});

test("条件を満たさない公開 prop はコントロールが出ない", () => {
  const selection = setupInstanceSelection({
    name: "card",
    ref: "sized-card",
    overrides: { widthMode: "hug" },
  });

  expect(publicPropNames(selection)).toEqual(["title", "widthMode"]);
});

test("インスタンスの上書きは、部品の値を上書きした形で着いたノードに乗る", () => {
  const targets = resolve(setupCard(), {
    name: "instance",
    ref: "card",
    overrides: { size: 10 },
  });

  expect(targetNamed(targets, "size").resolvedProps.width).toBe(10);
});

test("着いた先の既定は、インスタンスの上書きを当てる前の部品の値になる", () => {
  const targets = resolve(setupCard(), {
    name: "instance",
    ref: "card",
    overrides: { size: 10 },
  });

  expect(targetNamed(targets, "size").declared).toEqual(Option.some(5));
});

test("別のノードへ繋いだ公開 prop の上書きは、着いたノードに当たらない", () => {
  const targets = resolve(setupSplit(), {
    name: "instance",
    ref: "split",
    overrides: { widthB: 10 },
  });

  expect(targetNamed(targets, "widthA").resolvedProps.width).toBe(5);
});

test("入れ子の部品では、途中の参照ノードの上書きが着いたノードに当たり、インスタンスの上書きが勝つ", () => {
  const components: ComponentSet = {
    ...setupCard(),
    row: {
      type: "Box",
      children: [
        {
          name: "row-card",
          ref: "card",
          overrides: { size: 7, mode: "hug" },
        },
      ],
      publicProps: { rowSize: { node: "row-card", prop: "size" } },
    },
  };

  const targets = resolve(components, {
    name: "instance",
    ref: "row",
    overrides: { rowSize: 10 },
  });

  expect(targetNamed(targets, "rowSize").resolvedProps).toMatchObject({
    width: 10,
    widthMode: "hug",
  });
});

test("入れ子の部品では、着いた先の既定は途中の参照ノードの上書きまでを当て、インスタンスの上書きを当てる前の値になる", () => {
  const components: ComponentSet = {
    ...setupCard(),
    row: {
      type: "Box",
      children: [{ name: "row-card", ref: "card", overrides: { size: 7 } }],
      publicProps: { rowSize: { node: "row-card", prop: "size" } },
    },
  };

  const targets = resolve(components, {
    name: "instance",
    ref: "row",
    overrides: { rowSize: 10 },
  });

  expect(targetNamed(targets, "rowSize").declared).toEqual(Option.some(7));
});

test("同じノードの条件の prop を公開していれば、その公開名が条件の公開名になる", () => {
  const targets = resolve(setupCard(), { name: "instance", ref: "card" });

  expect(
    InstancePropTarget.conditionPublicName(
      targets,
      targetNamed(targets, "size"),
    ),
  ).toEqual(Option.some("mode"));
});

