  const components: ComponentSet = {
    first: {
      type: "Box",
      children: [{ name: "first-second", ref: "second" }],
      publicProps: { p: { node: "first-second", prop: "q" } },
    },
    second: {
      type: "Box",
      children: [{ name: "second-first", ref: "first" }],
      publicProps: { q: { node: "second-first", prop: "p" } },
